import subprocess

def check_pdftotext():
    try:
        result = subprocess.run(['pdftotext', '-v'], capture_output=True, text=True, check=True)
        print("pdftotext is available:", result.stdout)
    except subprocess.CalledProcessError as e:
        print("Error checking pdftotext:", e)

check_pdftotext()
